      cedFrameworkVersion: 'V.1',
      targetExamYear: null,
      examModeReference: 'hybrid-digital',
      officialSectionOne: '60 multiple-choice questions in 90 minutes; 50% of the official exam score.',
      officialSectionTwo: '7 free-response questions in 105 minutes; 50% of the official exam score.',
      pilotAlignment: '180-item internal foundation sampler across nine official units; 36 five-item banks; six chemistry science practices; text-first chapters; no FRQ scoring or laboratory competency claim.',
      lastVerifiedAt: verifiedAt,
